class SkipList {
  private a: number[] = [];

  private lower(x: number): number {
    let lo = 0, hi = this.a.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (this.a[mid] < x) lo = mid + 1; else hi = mid;
    }
    return lo;
  }

  search(target: number): boolean {
    const i = this.lower(target);
    return i < this.a.length && this.a[i] === target;
  }

  add(num: number): void {
    this.a.splice(this.lower(num), 0, num);
  }

  erase(num: number): boolean {
    const i = this.lower(num);
    if (i === this.a.length || this.a[i] !== num) return false;
    this.a.splice(i, 1);
    return true;
  }
}

