const MAX_LEVEL = 16;

class SkipNode {
  next: (SkipNode | null)[];
  constructor(public val: number, height: number) {
    this.next = new Array(height).fill(null);
  }
}

class SkipList {
  private head = new SkipNode(-1, MAX_LEVEL);

  // last node with value < num on each level
  private walk(num: number): SkipNode[] {
    const prev = new Array<SkipNode>(MAX_LEVEL);
    let cur = this.head;
    for (let lvl = MAX_LEVEL - 1; lvl >= 0; lvl--) {
      while (cur.next[lvl] && cur.next[lvl]!.val < num) cur = cur.next[lvl]!;
      prev[lvl] = cur;
    }
    return prev;
  }

  search(target: number): boolean {
    const nxt = this.walk(target)[0].next[0];
    return nxt !== null && nxt.val === target;
  }

  add(num: number): void {
    const prev = this.walk(num);
    let height = 1;
    while (height < MAX_LEVEL && Math.random() < 0.5) height++;
    const node = new SkipNode(num, height);
    for (let lvl = 0; lvl < height; lvl++) {
      node.next[lvl] = prev[lvl].next[lvl];
      prev[lvl].next[lvl] = node;
    }
  }

  erase(num: number): boolean {
    const prev = this.walk(num);
    const node = prev[0].next[0];
    if (!node || node.val !== num) return false;
    for (let lvl = 0; lvl < node.next.length; lvl++) {
      if (prev[lvl].next[lvl] === node) prev[lvl].next[lvl] = node.next[lvl];
    }
    return true;
  }
}

