import random

MAX_LEVEL = 16


class SkipNode:
    __slots__ = ("val", "next")

    def __init__(self, val: int, height: int):
        self.val = val
        self.next = [None] * height


class SkipList:
    def __init__(self):
        self.head = SkipNode(-1, MAX_LEVEL)

    def _walk(self, num: int):
        # last node with value < num on each level
        prev = [None] * MAX_LEVEL
        cur = self.head
        for lvl in range(MAX_LEVEL - 1, -1, -1):
            while cur.next[lvl] and cur.next[lvl].val < num:
                cur = cur.next[lvl]
            prev[lvl] = cur
        return prev

    def search(self, target: int) -> bool:
        nxt = self._walk(target)[0].next[0]
        return nxt is not None and nxt.val == target

    def add(self, num: int) -> None:
        prev = self._walk(num)
        height = 1
        while height < MAX_LEVEL and random.random() < 0.5:
            height += 1
        node = SkipNode(num, height)
        for lvl in range(height):
            node.next[lvl] = prev[lvl].next[lvl]
            prev[lvl].next[lvl] = node

    def erase(self, num: int) -> bool:
        prev = self._walk(num)
        node = prev[0].next[0]
        if node is None or node.val != num:
            return False
        for lvl in range(len(node.next)):
            if prev[lvl].next[lvl] is node:
                prev[lvl].next[lvl] = node.next[lvl]
        return True

